import {aggregate,ratio} from './analytics.js';
export const DAY=86400000;
export const iso=d=>new Date(d).toISOString().slice(0,10);
export function metrics(rows){const s=aggregate(rows);return {...s,ctr:ratio(s.clicks*100,s.impressions),cpc:ratio(s.spend,s.clicks),cpm:ratio(s.spend*1000,s.impressions),cvr:ratio(s.conversions*100,s.clicks),cpa:ratio(s.spend,s.conversions),roas:ratio(s.revenue,s.spend),engagementRate:rows.length&&rows.every(r=>Number.isFinite(r.engagements))?ratio(rows.reduce((n,r)=>n+r.engagements,0)*100,s.impressions):null}}
export function filterRows(rows,f={}){if(f.from&&f.to&&f.from>f.to)return [];return rows.filter(r=>(!f.from||r.date>=f.from)&&(!f.to||r.date<=f.to)&&(!f.channel||f.channel==='All channels'||r.channel===f.channel)&&(!f.campaign||r.campaign===f.campaign)&&(!f.objective||r.objective===f.objective))}
export function comparisonRange(from,to,mode='previous',custom={}){const valid=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d))&&new Date(d).toISOString().slice(0,10)===d;if(!valid(from)||!valid(to)||from>to)return null;if(mode==='custom')return valid(custom.from)&&valid(custom.to)&&custom.from<=custom.to?custom:null;if(mode==='month'){const d=new Date(from+'T00:00:00Z');return {from:iso(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-1,1)),to:iso(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),0))}}const days=Math.round((Date.parse(to)-Date.parse(from))/DAY)+1;return {from:iso(Date.parse(from)-days*DAY),to:iso(Date.parse(from)-DAY)}}
export function delta(current,previous){return {absolute:current===null||previous===null?null:current-previous,percent:current===null||previous===null||previous===0?null:(current-previous)/previous*100}}
export function funnel(rows){const m=metrics(rows);return [{name:'Impressions',value:m.impressions,rate:null,drop:null},{name:'Clicks',value:m.clicks,rate:ratio(m.clicks*100,m.impressions),drop:m.impressions?100-m.ctr:null},{name:'Conversions',value:m.conversions,rate:ratio(m.conversions*100,m.clicks),drop:m.clicks?100-m.cvr:null}]}
export function health(rows,{cpa=20,roas=2.5,cpaWeight=1,roasWeight=1}={}){const m=metrics(rows),checks=[];if(m.conversions>=5&&m.cpa!==null&&cpa>0&&cpaWeight>0)checks.push({name:'CPA target',weight:cpaWeight,pass:m.cpa<=cpa});if(m.conversions>=5&&m.roas!==null&&roas>0&&roasWeight>0)checks.push({name:'ROAS target',weight:roasWeight,pass:m.roas>=roas});const sum=checks.reduce((n,c)=>n+c.weight,0);return {score:sum?Math.round(checks.reduce((n,c)=>n+(c.pass?c.weight:0),0)/sum*100):null,checks,preliminary:m.conversions<30}}
export function signals(current,prior,threshold=20){const a=metrics(current),b=metrics(prior);if(!current.length||!prior.length)return [];return ['cpa','conversions','ctr','roas','spend'].flatMap(key=>{const d=delta(a[key],b[key]);return d.percent!==null&&Math.abs(d.percent)>=threshold?[{metric:key,change:d.percent,absolute:d.absolute,preliminary:a.conversions<30||b.conversions<30}]:[]})}
export function projectBudget(rows,allocations,efficiency=1){return [...new Set(rows.map(r=>r.channel))].map(channel=>{const selected=rows.filter(r=>r.channel===channel),m=metrics(selected),budget=Number(allocations[channel]);if(!Number.isFinite(budget)||budget<0||budget>1e7||!Number.isFinite(efficiency)||efficiency<0||efficiency>2)throw Error('Invalid budget assumptions');const adequate=m.spend>0&&m.conversions>=5&&new Set(selected.map(r=>r.date)).size>=7;return {channel,baseline:m.spend,budget,conversions:adequate?m.conversions/m.spend*budget*efficiency:null,revenue:adequate?m.roas*budget*efficiency:null}})}
export function ice(impact,confidence,effort){return [impact,confidence,effort].every(v=>Number.isFinite(v)&&v>=1&&v<=10)?impact*confidence/effort:null}
export function groupCampaigns(rows){return [...new Set(rows.map(r=>r.campaign))].map(campaign=>({campaign,...metrics(rows.filter(r=>r.campaign===campaign))}))}
export function evidence(rows,filters,previous=[]){return {filters,recordCount:rows.length,campaignCount:new Set(rows.map(r=>r.campaign)).size,totals:metrics(rows),channels:[...new Set(rows.map(r=>r.channel))].map(channel=>({channel,...metrics(rows.filter(r=>r.channel===channel))})),campaigns:groupCampaigns(rows).slice(0,20),campaignsTruncated:new Set(rows.map(r=>r.campaign)).size>20,previous:previous.length?metrics(previous):null}}
export function answerQuestion(question,context){const q=question.toLowerCase(),m=context.totals,fmt=v=>v===null?'unavailable':Number(v.toFixed(2)).toLocaleString('en-US');let text;
 if(!context.recordCount){text='No records match your selection. Adjust the date range or clear a campaign filter before asking for an interpretation.'}
 else if(/(chang|previous|declin|why|increas|decreas)/.test(q)){const prior=context.previous;const key=/cpa|acquisition/.test(q)?'cpa':/roas|return/.test(q)?'roas':null;if(!prior)text='There are no comparison observations for these filters. Enable comparison and select a period with earlier data.';else if(key){const d=delta(m[key],prior[key]);text=`${key.toUpperCase()} is ${fmt(m[key])} versus ${fmt(prior[key])} previously; absolute change ${fmt(d.absolute)}, relative change ${fmt(d.percent)}%. Spend changed from $${fmt(prior.spend)} to $${fmt(m.spend)}; conversions from ${fmt(prior.conversions)} to ${fmt(m.conversions)}. Review channel mix, tracking and conversion quality. These observations do not establish why performance changed.`}else text=`Revenue changed by $${fmt(m.revenue-prior.revenue)}, spend by $${fmt(m.spend-prior.spend)}, and conversions by ${fmt(m.conversions-prior.conversions)}. Compare channel mix and measurement quality before testing a cause. This data does not establish causality.`}
 else if(/(roas|return|budget|channel)/.test(q)){const ranked=context.channels.filter(c=>c.roas!==null).sort((a,b)=>b.roas-a.roas);text=ranked.length?`Observed channel ROAS: ${ranked.map(c=>`${c.channel} ${fmt(c.roas)}×`).join('; ')}. ${ranked[0].channel} leads this selection. Validate margin, attribution, and audience overlap before testing additional budget.`:'No spend-based channel comparison is available.'}
 else if(/(cpa|campaign|cost)/.test(q)){const ranked=context.campaigns.filter(c=>c.cpa!==null).sort((a,b)=>a.cpa-b.cpa);text=ranked.length?`Campaign CPA (USD, lowest first): ${ranked.map(c=>`${c.campaign}: $${fmt(c.cpa)}`).join('; ')}. Confirm that conversions represent comparable business outcomes.`:'No campaign has conversions available for a CPA comparison.'}
 else if(/(chang|previous|declin|why)/.test(q)){text=context.previous?`Compared with the selected comparison period, revenue changed by $${fmt(m.revenue-context.previous.revenue)}, spend by $${fmt(m.spend-context.previous.spend)}, and conversions by ${fmt(m.conversions-context.previous.conversions)}. These are observations. Creative fatigue, audience mix, tracking changes, and seasonality are hypotheses; this data cannot determine the cause.`:'There are no comparison observations for these filters. Select a later or custom reporting period. Causes cannot be established from these metrics alone.'}
 else if(/(missing|limit|engagement|reach)/.test(q)){text='The core CSV does not establish unique reach, incremental lift, customer lifetime value, attribution quality, or fixed costs. Engagement rate is only available if engagements were supplied. Missing observations are not assumed to be zero.'}
 else{text=`Selected ${context.recordCount} records across ${context.campaignCount} campaigns. Attributed revenue $${fmt(m.revenue)} on spend $${fmt(m.spend)}; ROAS ${fmt(m.roas)}×; conversions ${fmt(m.conversions)}; CPA $${fmt(m.cpa)}. Prioritize measurement quality, then test one controlled creative or audience change. A general business question outside these metrics needs more context.`}
 return `Calculated local answer\n${context.campaignsTruncated?'Campaign evidence is limited to the first 20 campaign groups. ':''}${text}\n\nScope: ${context.filters.from} to ${context.filters.to}. Observed associations do not establish causality or profit.`}
export function loadArray(storage,key){try{const value=JSON.parse(storage.getItem(key)||'[]');return Array.isArray(value)?value.filter(v=>v&&typeof v==='object').slice(0,50):[]}catch{return []}}
